12: func queuedTaskDependants(ctx context.Context, db *store.DB, projectID int64, predecessor store.Task) ([]store.Task, error) {
13: 	tasks, err := db.Tasks(ctx, projectID, true)
14: 	if err != nil {
15: 		return nil, err
16: 	}
17: 	predecessorID := taskIDString(predecessor.Seq)
18: 	dependants := make([]store.Task, 0)
19: 	for _, task := range tasks {
20: 		if task.State != store.StateQueued {
21: 			continue
22: 		}
23: 		plan, err := task.AdmittedPlan()
24: 		if err != nil {
25: 			return nil, admittedPlanFailure(err)
26: 		}
27: 		if plan == nil {
28: 			continue
29: 		}
30: 		for _, dependency := range plan.Dependencies {
31: 			if dependency.TaskID == predecessorID {
32: 				dependants = append(dependants, task)
33: 				break
34: 			}
35: 		}
36: 	}
37: 	return dependants, nil
38: }
