	if err := db.QueryRowContext(ctx, `SELECT project_id FROM tasks WHERE id=?`, taskID).Scan(&projectID); err != nil {
		return err
	}
	task, err := db.TaskByID(ctx, projectID, taskID)
	if err != nil {
		return err
	}
	project, err := db.ProjectByID(ctx, projectID)
