			}
		}
	} else if !errors.Is(readErr, os.ErrNotExist) {
		return readErr
	}
	sort.Slice(markers, func(i, j int) bool { return markers[i].Repo < markers[j].Repo })
	plans, err := db.TaskPlanRevisions(ctx, taskID)
	if err != nil {
		return err
	}
	budgetUsage, err := db.TaskBudgetUsage(ctx, taskID)
	if err != nil {
		return err
	}
	budgetCrossings, err := db.TaskBudgetCrossings(ctx, taskID)
	if err != nil {
		return err
	}
	turnToken, err := db.TaskTurnToken(ctx, taskID)
	if err != nil {
		return err
	}
	if admitted != nil {
		if len(plans) < admitted.Revision {
			return fmt.Errorf("missing plan revision history for Task %d", taskID)
		}
		plans = plans[:admitted.Revision]
