		} else if !errors.Is(err, ErrNotFound) {
			return err
		}
	}
	if snapshot.ReviewReceipts, err = db.ReviewReceipts(ctx, taskID); err != nil {
		return err
	}
	if task.Type == "change" {
		if snapshot.ValidationCandidates, err = db.ValidationCandidates(ctx, taskID); err != nil {
			return err
		}
		if snapshot.ValidationStages, err = db.ValidationStages(ctx, taskID); err != nil {
			return err
		}
		validationState, err := db.validationStateForTask(ctx, taskID)
		if err != nil {
			return err
		}
		snapshot.ReviewRounds = validationState.ReviewRounds
		snapshot.ReviewPatterns = validationState.ReviewPatterns
		snapshot.ReviewFindings = validationState.ReviewFindings
		snapshot.ReviewFindingEvents = validationState.ReviewFindingEvents
		snapshot.ProviderFindingPatterns = validationState.ProviderFindingPatterns
		snapshot.ProviderFindings = validationState.ProviderFindings
		snapshot.ProviderFindingEvents = validationState.ProviderFindingEvents
		snapshot.FixRoundProviderFindings = validationState.FixRoundProviderFindings
		snapshot.ReviewCarries = validationState.ReviewCarries
		snapshot.ReviewDispositions = validationState.ReviewDispositions
		grant, err := db.ReviewCapGrant(ctx, taskID)
		if err == nil {
			snapshot.ReviewCapGrant = &grant
		} else if !IsNotFound(err) {
			return err
		}
		snapshot.ValidationFixRounds = validationState.ValidationFixRounds
	}
	if project.IsWorkspace() {
		if snapshot.Members, err = db.ProjectRepos(ctx, projectID); err != nil {
			return err
		}
		if snapshot.TaskRepos, err = db.TaskRepos(ctx, taskID); err != nil {
			return err
		}
	}
	var encoded bytes.Buffer
	if err := toml.NewEncoder(&encoded).Encode(snapshot); err != nil {
		return err
	}
	if err := atomicfile.Write(db.TaskSnapshotPath(project.Name, task.Seq), encoded.Bytes(), 0o600); err != nil {
		return err
	}
	if persistProject {
		return db.PersistProject(ctx, projectID)
	}
	return nil
}

