func (db *DB) persistTask(ctx context.Context, taskID int64, persistProject bool) error {
	var projectID int64
	if err := db.QueryRowContext(ctx, `SELECT project_id FROM tasks WHERE id=?`, taskID).Scan(&projectID); err != nil {
		return err
	}
	task, err := db.TaskByID(ctx, projectID, taskID)
	if err != nil {
		return err
	}
	project, err := db.ProjectByID(ctx, projectID)
	if err != nil {
		return err
	}
	if task.PlanJSON != "" {
		// Serialize admitted snapshots across processes. A writer that began
		// before a revision must not overwrite that revision's recovery file.
		path := db.TaskSnapshotPath(project.Name, task.Seq)
		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
			return err
		}
		lock, err := acquireStoreFileLock(ctx, path+".lock", "Task snapshot")
		if err != nil {
			return err
		}
		defer lock.Close()
		task, err = db.TaskByID(ctx, projectID, taskID)
		if err != nil {
			return err
		}
	}
	admitted, err := task.AdmittedPlan()
	if err != nil {
		return err
	}
	identities, err := db.TaskLaunchIdentities(ctx, taskID)
	if err != nil {
		return err
	}
	adoptions, err := db.TaskAdoptions(ctx, taskID)
	if err != nil {
		return err
	}
	branchAuthors, err := db.BranchAuthorsForTask(ctx, taskID)
	if err != nil {
		return err
	}
	invalidatedReviewVerdicts, err := db.InvalidatedReviewVerdictsForChange(ctx, taskID)
	if err != nil {
		return err
	}
	// A launch or revision may commit while this snapshot is being captured.
	// Include only history belonging to the Task row captured above.
	if admitted != nil {
		captured := identities[:0]
		for _, identity := range identities {
			if identity.LaunchNumber <= task.Launches && identity.PlanRevision <= admitted.Revision {
				captured = append(captured, identity)
			}
		}
		identities = captured
	}
	reportReviews, err := db.ReportReviewsForTask(ctx, taskID)
	if err != nil {
		return err
	}
	reportAcceptance, err := db.ReportAcceptanceForTask(ctx, taskID)
	if err != nil {
		return err
	}
	markers, err := db.PRBodyMarkersForTask(ctx, taskID)
	if err != nil {
		return err
	}
	watchFailures, err := db.PRTaskWatchFailuresForTask(ctx, taskID)
	if err != nil {
		return err
	}
	targetChanges, err := db.TaskTargetChanges(ctx, taskID)
	if err != nil {
		return err
	}
	deliveries, err := db.TaskDeliveries(ctx, taskID)
	if err != nil {
		return err
	}
	deliveryOperations, err := db.taskDeliveryOperations(ctx, taskID)
	if err != nil {
		return err
	}
	snapshotPath := db.TaskSnapshotPath(project.Name, task.Seq)
	if data, readErr := os.ReadFile(snapshotPath); readErr == nil {
		var previous TaskSnapshot
		if _, err := toml.Decode(string(data), &previous); err != nil {
			return fmt.Errorf("decode existing Task snapshot %s: %w", snapshotPath, err)
		}
		known := make(map[string]struct{}, len(markers))
		for _, marker := range markers {
			known[marker.Repo] = struct{}{}
		}
		for _, marker := range previous.PRBodyMarkers {
			if marker.TaskID == taskID {
				if _, exists := known[marker.Repo]; !exists {
					markers = append(markers, marker)
					known[marker.Repo] = struct{}{}
