40: func (s *Service) holdQueuedDependants(ctx context.Context, db *store.DB, project store.Project, predecessor store.Task) ([]string, error) {
41: 	dependants, err := queuedTaskDependants(ctx, db, project.ID, predecessor)
42: 	if err != nil || len(dependants) == 0 {
43: 		return nil, err
44: 	}
45: 	ids := make([]string, 0, len(dependants))
46: 	for _, dependant := range dependants {
47: 		dependentRef := taskIDString(dependant.Seq)
48: 		ids = append(ids, dependentRef)
49: 		if err := db.ObsoleteDependencyDecision(ctx, dependant.ID, dependentRef, taskIDString(predecessor.Seq)); err != nil {
50: 			return nil, err
51: 		}
52: 	}
53: 	origin := "teardown-dependants:" + taskIDString(predecessor.Seq) + ":" + strings.Join(ids, ",")
54: 	_, err = db.RaiseDecision(ctx, store.DecisionRequest{
55: 		ProjectID: project.ID,
56: 		TaskID:    predecessor.ID,
57: 		Origin:    origin,
58: 		Kind:      "teardown_dependants",
59: 		Question:  fmt.Sprintf("Tearing down %s left queued dependants %s. Re-point them to a replacement Task, or cascade their teardown?", taskIDString(predecessor.Seq), strings.Join(ids, ", ")),
60: 		Options:   []string{"re-point", "cascade"},
61: 	})
62: 	return ids, err
63: }
64: 
65: func teardownDecisionDependants(ctx context.Context, db *store.DB, project store.Project, decision store.Decision) (store.Task, []store.Task, error) {
66: 	predecessor, err := db.TaskByID(ctx, project.ID, decision.TaskID)
67: 	if err != nil {
68: 		return store.Task{}, nil, err
69: 	}
70: 	parts := strings.Split(decision.Origin, ":")
71: 	if len(parts) != 3 || parts[0] != "teardown-dependants" || parts[1] != taskIDString(predecessor.Seq) {
72: 		return store.Task{}, nil, fmt.Errorf("teardown dependant Decision binding is invalid")
73: 	}
74: 	dependants := make([]store.Task, 0)
75: 	for _, taskRef := range strings.Split(parts[2], ",") {
76: 		dependant, err := db.Task(ctx, project.ID, taskRef)
77: 		if err != nil {
78: 			return store.Task{}, nil, fmt.Errorf("queued dependant %s no longer exists", taskRef)
79: 		}
80: 		if dependant.State != store.StateQueued {
81: 			continue
82: 		}
83: 		plan, err := dependant.AdmittedPlan()
84: 		if err != nil {
85: 			return store.Task{}, nil, admittedPlanFailure(err)
86: 		}
87: 		if plan == nil {
88: 			continue
89: 		}
90: 		for _, dependency := range plan.Dependencies {
91: 			if dependency.TaskID == taskIDString(predecessor.Seq) {
92: 				dependants = append(dependants, dependant)
93: 				break
94: 			}
95: 		}
96: 	}
97: 	return predecessor, dependants, nil
98: }
99: 
100: func validateTeardownRepoint(ctx context.Context, db *store.DB, project store.Project, decision store.Decision, replacement store.Task) error {
101: 	predecessor, dependants, err := teardownDecisionDependants(ctx, db, project, decision)
102: 	if err != nil {
103: 		return err
104: 	}
105: 	if replacement.ID == predecessor.ID {
106: 		return fmt.Errorf("replacement Task must differ from the torn-down predecessor")
107: 	}
108: 	for _, dependant := range dependants {
109: 		plan, err := dependant.AdmittedPlan()
110: 		if err != nil {
111: 			return admittedPlanFailure(err)
112: 		}
113: 		for _, dependency := range plan.Dependencies {
114: 			if dependency.TaskID != taskIDString(predecessor.Seq) {
115: 				continue
116: 			}
117: 			if replacement.Seq >= dependant.Seq {
118: 				return fmt.Errorf("replacement Task %s must precede dependant %s", taskIDString(replacement.Seq), taskIDString(dependant.Seq))
119: 			}
120: 			validType := dependency.Milestone == "landed" && replacement.Type == "change" || dependency.Milestone == "reported" && (replacement.Type == "research" || replacement.Type == "review") || dependency.Milestone == "accepted" && replacement.Type == "research" && (replacement.ReportKind == "spec" || replacement.ReportKind == "tickets")
121: 			if !validType {
122: 				return fmt.Errorf("replacement Task %s cannot satisfy %s", taskIDString(replacement.Seq), dependency.Milestone)
123: 			}
124: 		}
125: 	}
126: 	return nil
127: }
128: 
129: func (s *Service) applyTeardownDependantsDecision(ctx context.Context, db *store.DB, project store.Project, cfg config.Config, decision store.Decision) error {
130: 	predecessor, dependants, err := teardownDecisionDependants(ctx, db, project, decision)
131: 	if err != nil {
132: 		return err
133: 	}
134: 	if len(dependants) == 0 {
135: 		return nil
136: 	}
137: 	if decision.Answer == "cascade" {
138: 		for _, dependant := range dependants {
139: 			if err := db.Transition(ctx, dependant.ID, store.StateQueued, store.StateTornDown, "cli", "Cascade teardown approved for predecessor "+taskIDString(predecessor.Seq)); err != nil && err != store.ErrStateRace {
140: 				return err
141: 			}
142: 			if err := db.ObsoleteTaskDecisions(ctx, dependant.ID); err != nil {
143: 				return err
144: 			}
145: 		}
146: 		return nil
147: 	}
148: 	if decision.Answer != "re-point" || !strings.HasPrefix(decision.AnswerReason, "to=") {
149: 		return fmt.Errorf("re-point requires a replacement Task ID")
150: 	}
151: 	replacementID := strings.TrimPrefix(decision.AnswerReason, "to=")
152: 	replacement, err := db.Task(ctx, project.ID, replacementID)
153: 	if err != nil {
154: 		return fmt.Errorf("replacement Task %s does not exist", replacementID)
155: 	}
156: 	if err := validateTeardownRepoint(ctx, db, project, decision, replacement); err != nil {
157: 		return err
158: 	}
159: 	updates := make([]store.TaskPlanRevision, 0, len(dependants))
160: 	for _, dependant := range dependants {
161: 		plan, err := dependant.AdmittedPlan()
162: 		if err != nil {
163: 			return admittedPlanFailure(err)
164: 		}
165: 		if plan == nil {
166: 			return fmt.Errorf("queued dependant %s has no admitted plan", taskIDString(dependant.Seq))
167: 		}
168: 		revised := *plan
169: 		for _, dependency := range plan.Dependencies {
170: 			if dependency.TaskID != taskIDString(predecessor.Seq) {
171: 				continue
172: 			}
173: 			revised, err = revised.RepointDependency(dependency.TaskID, taskIDString(replacement.Seq), dependency.Milestone)
174: 			if err != nil {
175: 				return err
176: 			}
177: 		}
178: 		updates = append(updates, store.TaskPlanRevision{Task: dependant, Plan: revised})
179: 	}
180: 	if err := db.ReviseTaskPlans(ctx, updates); err != nil {
181: 		return err
182: 	}
183: 	_, err = s.refillQueuedTasks(ctx, db, project, cfg, false)
184: 	return err
185: }
